drop policy if exists fixture_results_select_public_or_member on public.fixture_results;
create policy fixture_results_select_anon_public on public.fixture_results for select to anon using (exists(select 1 from public.fixtures f join public.seasons s on s.id=f.season_id join public.leagues l on l.id=s.league_id where f.id=fixture_results.fixture_id and s.is_public=true and l.is_published=true));
create policy fixture_results_select_authenticated_public_or_admin on public.fixture_results for select to authenticated using (public.has_platform_role() or exists(select 1 from public.fixtures f join public.seasons s on s.id=f.season_id join public.leagues l on l.id=s.league_id where f.id=fixture_results.fixture_id and s.is_public=true and l.is_published=true));
drop policy if exists fixtures_select_public_or_member on public.fixtures;
create policy fixtures_select_anon_public on public.fixtures for select to anon using (exists(select 1 from public.seasons s join public.leagues l on l.id=s.league_id where s.id=fixtures.season_id and s.is_public=true and l.is_published=true));
create policy fixtures_select_authenticated_public_or_member_or_admin on public.fixtures for select to authenticated using (public.has_platform_role() or exists(select 1 from public.seasons s join public.leagues l on l.id=s.league_id where s.id=fixtures.season_id and s.is_public=true and l.is_published=true) or public.is_active_team_member(home_team_id) or public.is_active_team_member(away_team_id));
drop policy if exists leagues_select_published on public.leagues;
create policy leagues_select_anon_published on public.leagues for select to anon using (is_published=true);
create policy leagues_select_authenticated_published_or_admin on public.leagues for select to authenticated using (is_published=true or public.has_platform_role());
drop policy if exists locations_select_active on public.locations;
create policy locations_select_anon_active on public.locations for select to anon using (is_active=true);
create policy locations_select_authenticated_active_or_admin on public.locations for select to authenticated using (is_active=true or public.has_platform_role());
drop policy if exists season_teams_select_public_or_member on public.season_teams;
create policy season_teams_select_anon_public on public.season_teams for select to anon using (registration_status='approved' and exists(select 1 from public.seasons s join public.leagues l on l.id=s.league_id where s.id=season_teams.season_id and s.is_public=true and l.is_published=true));
create policy season_teams_select_authenticated_public_or_member_or_admin on public.season_teams for select to authenticated using (public.has_platform_role() or (registration_status='approved' and exists(select 1 from public.seasons s join public.leagues l on l.id=s.league_id where s.id=season_teams.season_id and s.is_public=true and l.is_published=true)) or public.is_active_team_member(id));
drop policy if exists seasons_select_public on public.seasons;
create policy seasons_select_anon_public on public.seasons for select to anon using (is_public=true and exists(select 1 from public.leagues l where l.id=seasons.league_id and l.is_published=true));
create policy seasons_select_authenticated_public_or_admin on public.seasons for select to authenticated using (public.has_platform_role() or (is_public=true and exists(select 1 from public.leagues l where l.id=seasons.league_id and l.is_published=true)));
revoke all on function public.has_platform_role() from public,anon;
revoke all on function public.is_active_team_captain(uuid) from public,anon;
revoke all on function public.is_active_team_member(uuid) from public,anon;
grant execute on function public.has_platform_role() to authenticated,service_role;
grant execute on function public.is_active_team_captain(uuid) to authenticated,service_role;
grant execute on function public.is_active_team_member(uuid) to authenticated,service_role;